@import url('https://fonts.googleapis.com/css2?family=Barlow+Condensed:wght@500;600;700;800;900&family=DM+Sans:wght@400;500;600;700&display=swap');
:root{--ink:#f5f4fa;--muted:#a6a6b6;--lime:#d6fb55;--pink:#fa658a;--panel:rgba(22,24,38,.78);--line:rgba(255,255,255,.13)}*{box-sizing:border-box}html,body{height:100%;margin:0;background:#10131e;color:var(--ink);font-family:'DM Sans',sans-serif;overflow:hidden}button{font:inherit;color:inherit;cursor:pointer}#app{position:relative;width:100%;height:100%;min-height:500px;overflow:hidden;background:#10131e}#game,#vignette{position:absolute;inset:0;width:100%;height:100%}#game{display:block}#vignette{pointer-events:none;background:radial-gradient(ellipse at 56% 45%,transparent 35%,rgba(5,7,15,.55) 100%),linear-gradient(90deg,rgba(8,10,19,.68),transparent 67%)}.chrome{position:absolute;z-index:5;top:0;left:0;right:0;height:82px;padding:0 5.2%;display:flex;align-items:center;justify-content:space-between;border-bottom:1px solid rgba(255,255,255,.08);background:linear-gradient(180deg,rgba(10,12,22,.55),transparent)}.brand{display:flex;align-items:center;gap:12px;font:800 21px 'Barlow Condensed',sans-serif;letter-spacing:1.6px}.brand b{color:var(--lime)}.brand small{display:block;font:600 8px 'DM Sans';letter-spacing:2.7px;color:#a6a6b6;margin-top:3px}.brand-mark{display:grid;place-items:center;width:36px;height:36px;color:#111626;background:var(--lime);font-size:21px;clip-path:polygon(25% 0,100% 0,75% 100%,0 100%)}.top-right{display:flex;align-items:center;gap:23px}.currency{display:flex;align-items:center;gap:9px;font:700 15px 'Barlow Condensed';letter-spacing:1px}.currency i{font-style:normal;color:var(--lime);font-size:20px}.icon-btn,.back-btn{background:rgba(255,255,255,.06);border:1px solid var(--line);border-radius:4px;padding:9px 13px}.screen{position:absolute;inset:0;z-index:3;display:none;animation:rise .36s ease both}.screen.visible{display:block}.home-copy{position:absolute;top:23%;left:10%;width:min(440px,40vw)}.eyebrow{font-size:10px;font-weight:700;letter-spacing:2.4px;color:var(--lime)}.pulse{display:inline-block;width:7px;height:7px;border-radius:50%;background:var(--lime);box-shadow:0 0 12px var(--lime);margin-right:8px}h1,h2,h3,p{margin-top:0}h1{font:900 clamp(54px,7vw,98px)/.87 'Barlow Condensed',sans-serif;letter-spacing:-1px;margin:21px 0 19px}h1 em,h2 em{font-style:normal;color:var(--lime)}.home-copy>p{max-width:360px;font-size:13px;line-height:1.8;color:#b8bac7}.home-actions{display:flex;align-items:center;gap:14px;margin-top:28px}.primary{background:var(--lime);color:#141824;border:0;border-radius:3px;padding:16px 21px;font:800 14px 'Barlow Condensed';letter-spacing:1.5px;box-shadow:0 7px 25px rgba(214,251,85,.13);transition:.2s}.primary:hover{transform:translateY(-2px);box-shadow:0 10px 32px rgba(214,251,85,.25)}.primary span{font-size:18px;margin-left:20px}.quiet{background:transparent;border:0;font:700 11px 'DM Sans';letter-spacing:1.2px;padding:14px;color:#cacbd4}.quiet span{color:var(--lime);margin-left:8px}.home-stats{display:flex;gap:35px;margin-top:48px}.home-stats div{display:flex;flex-direction:column;gap:4px}.home-stats b{font:700 27px 'Barlow Condensed';color:white}.home-stats small{font-size:8px;color:#9b9eae;letter-spacing:1.8px}.hero-card{position:absolute;width:min(34vw,440px);height:min(67vh,540px);right:12%;top:17%;border:1px solid rgba(255,255,255,.14);background:linear-gradient(145deg,rgba(93,56,86,.46),rgba(22,24,38,.2) 53%,rgba(14,17,28,.8));overflow:hidden;clip-path:polygon(8% 0,100% 0,100% 89%,92% 100%,0 100%,0 8%)}.hero-card:before{content:'';position:absolute;inset:0;background:linear-gradient(140deg,transparent 45%,rgba(249,97,135,.22)),repeating-linear-gradient(130deg,transparent 0 24px,rgba(255,255,255,.025) 25px 26px)}.hero-orbit{position:absolute;width:74%;aspect-ratio:1;border:1px solid rgba(214,251,85,.48);border-radius:50%;top:11%;left:13%;box-shadow:0 0 50px rgba(245,87,135,.16),inset 0 0 70px rgba(245,87,135,.16)}.hero-sigil{position:absolute;right:10%;top:11%;font-size:98px;font-family:serif;color:rgba(255,255,255,.07)}.hero-figure{position:absolute;left:31%;top:19%;height:66%;width:40%;filter:drop-shadow(0 15px 25px rgba(250,61,106,.34));animation:idle 2s ease-in-out infinite}.hero-head{position:absolute;left:28%;top:6%;width:46%;height:24%;background:#ffbf91;border-radius:48% 48% 42% 42%;z-index:3}.hero-head:before{content:'';position:absolute;left:-9%;top:-19%;width:118%;height:42%;background:#ff7f2e;clip-path:polygon(0 0,100% 0,79% 100%,66% 45%,53% 100%,39% 40%,24% 100%,12% 48%)}.hero-head i{position:absolute;width:54%;height:6px;left:23%;top:48%;background:#25354a;border-bottom:2px solid #222;border-radius:20px}.hero-body{position:absolute;left:15%;top:27%;width:70%;height:47%;background:linear-gradient(100deg,#25283a 0 25%,#ff7b32 26% 73%,#e35e30 74%);clip-path:polygon(24% 0,76% 0,100% 18%,82% 100%,18% 100%,0 18%);z-index:2}.hero-cape{position:absolute;left:9%;top:31%;width:83%;height:50%;background:#20324a;clip-path:polygon(23% 0,75% 0,100% 100%,56% 82%,8% 100%,0 16%);z-index:1}.hero-leg{position:absolute;top:69%;height:29%;width:24%;background:#242536;z-index:2}.hero-leg.left{left:25%;transform:skew(-8deg)}.hero-leg.right{right:25%;transform:skew(8deg)}.hero-aura{position:absolute;inset:3% -25%;background:radial-gradient(ellipse,rgba(255,97,111,.19),transparent 60%);z-index:-1}.hero-caption{position:absolute;bottom:8%;left:9%;display:flex;flex-direction:column;gap:6px}.hero-caption small{font-size:8px;letter-spacing:1.8px;color:var(--lime)}.hero-caption b{font:700 24px 'Barlow Condensed';letter-spacing:1px}.hero-index{position:absolute;right:8%;bottom:8%;font:700 21px 'Barlow Condensed'}.hero-index span{font-size:13px;color:#8f91a0}.home-bottom{position:absolute;bottom:28px;left:5.2%;right:5.2%;display:flex;justify-content:space-between;font-size:8px;letter-spacing:1.8px;color:#8c8f9e}.screen-head{position:absolute;top:14%;left:8%;right:8%;display:flex;justify-content:space-between;align-items:flex-end}.screen-head h2{font:800 44px 'Barlow Condensed';letter-spacing:.5px;margin:7px 0 0}.back-btn{font-size:9px;letter-spacing:1.5px;padding:11px 15px}.character-layout{position:absolute;top:27%;left:8%;right:8%;bottom:12%;display:grid;grid-template-columns:31% 1fr;gap:30px}.character-detail{position:relative;border:1px solid var(--line);background:linear-gradient(145deg,rgba(51,48,69,.65),rgba(17,19,30,.8));padding:25px;overflow:hidden}.detail-art{position:absolute;right:10%;top:4%;height:55%;width:48%;opacity:.95}.detail-art .hero-figure{position:absolute;left:17%;top:3%;height:98%;width:66%}.detail-tag{font-size:9px;letter-spacing:1.8px;color:var(--lime)}.detail-info{position:absolute;bottom:23px;left:25px;right:25px}.detail-info h3{font:800 38px/.95 'Barlow Condensed';margin:7px 0}.detail-info p{font-size:10px;color:#aaaebe}.stat-list{display:grid;grid-template-columns:1fr 1fr;gap:8px 14px;margin:16px 0}.stat{font-size:8px;letter-spacing:1px;color:#a4a6b4}.stat i{display:block;margin-top:5px;height:3px;background:#3b3e4c}.stat i:after{content:'';display:block;width:var(--v);height:100%;background:var(--lime)}.ability-label{font-size:8px;letter-spacing:1.6px;color:#9598a7}.ability-name{font:700 17px 'Barlow Condensed';margin-top:4px}.roster-wrap{min-width:0;display:flex;flex-direction:column}.filter-row{display:flex;gap:8px;margin-bottom:12px}.filter-chip{padding:8px 13px;border:1px solid var(--line);background:rgba(255,255,255,.035);font-size:8px;letter-spacing:1px;color:#aaaebe}.filter-chip.active{background:var(--lime);color:#171a24;border-color:var(--lime)}.roster{display:grid;grid-template-columns:repeat(5,minmax(80px,1fr));gap:9px;overflow:auto;padding:2px 3px 8px}.runner-card{position:relative;min-height:118px;border:1px solid rgba(255,255,255,.11);background:linear-gradient(145deg,var(--card-color),rgba(23,25,38,.8) 74%);cursor:pointer;padding:9px;text-align:left;overflow:hidden;transition:.18s}.runner-card:hover,.runner-card.active{border-color:var(--lime);transform:translateY(-2px)}.runner-card.active:after{content:'✓';position:absolute;right:7px;top:5px;color:var(--lime);font-weight:bold}.runner-avatar{position:absolute;right:8px;top:8px;width:43px;height:66px;transform:scale(.62);transform-origin:top right;filter:drop-shadow(0 3px 5px #12131b)}.runner-card b{position:absolute;bottom:25px;left:9px;right:5px;font:700 13px 'Barlow Condensed';line-height:1}.runner-card small{position:absolute;bottom:9px;left:9px;font-size:7px;color:#b7b9c5;letter-spacing:.5px}.screen-footer{position:absolute;bottom:4%;left:8%;right:8%;display:flex;justify-content:space-between;color:#9295a3;font-size:8px;letter-spacing:1.5px}.screen-footer b{color:var(--lime);margin-left:7px}.world-grid{position:absolute;top:30%;left:9%;right:9%;height:43%;display:grid;grid-template-columns:repeat(4,1fr);gap:13px}.world-card{position:relative;border:1px solid var(--line);background:linear-gradient(160deg,var(--world),#151722 72%);text-align:left;padding:17px;overflow:hidden;cursor:pointer;transition:.2s}.world-card:before{content:'';position:absolute;inset:0;background:linear-gradient(0deg,rgba(11,13,22,.9),transparent 75%),repeating-linear-gradient(130deg,transparent 0 20px,rgba(255,255,255,.025) 21px 22px)}.world-card:hover,.world-card.active{border-color:var(--lime);transform:translateY(-4px)}.world-art{position:absolute;inset:0;opacity:.72}.world-art:before,.world-art:after{content:'';position:absolute;bottom:13%;background:var(--accent);opacity:.28;filter:blur(.5px)}.world-art:before{width:26%;height:57%;left:10%;clip-path:polygon(0 12%,50% 0,100% 13%,90% 100%,7% 100%)}.world-art:after{width:40%;height:73%;right:5%;clip-path:polygon(0 21%,15% 21%,15% 4%,40% 4%,40% 21%,58% 21%,58% 0,76% 0,76% 25%,100% 25%,100% 100%,0 100%)}.world-glyph{position:absolute;right:14px;top:8px;font:90px serif;color:rgba(255,255,255,.1)}.world-card-content{position:absolute;bottom:17px;left:17px}.world-card small{font-size:8px;color:var(--accent);letter-spacing:1.7px}.world-card h3{font:800 26px 'Barlow Condensed';margin:5px 0}.world-card p{font-size:9px;color:#b5b7c3;margin:0}.world-bottom{position:absolute;left:9%;right:9%;bottom:10%;display:flex;justify-content:space-between;align-items:center}.world-selected{font-size:9px;color:#aaaebe;letter-spacing:1.4px}.world-selected b{color:white;font-size:13px;margin-left:7px}.guide-grid{position:absolute;top:33%;left:12%;right:12%;display:grid;grid-template-columns:repeat(4,1fr);gap:14px}.guide-grid article{min-height:240px;padding:23px;border:1px solid var(--line);background:rgba(24,27,42,.73)}.guide-grid article>b{color:var(--lime);font:800 32px 'Barlow Condensed'}.guide-grid h3{font:700 20px 'Barlow Condensed';letter-spacing:1px;margin:27px 0 10px}.guide-grid p{font-size:11px;line-height:1.8;color:#aeb1bd;min-height:65px}.guide-grid span{font:700 11px 'Barlow Condensed';letter-spacing:1.5px;color:var(--lime)}.modal-screen{background:rgba(8,10,18,.64);backdrop-filter:blur(7px);align-items:center;justify-content:center}.screen.modal-screen.visible{display:flex}.modal-card{width:min(420px,90vw);border:1px solid rgba(255,255,255,.17);background:linear-gradient(145deg,#28283b,#161824);padding:36px;text-align:center;box-shadow:0 25px 100px #05060b}.modal-card h2{font:800 38px 'Barlow Condensed';margin:9px 0}.modal-card p{font-size:12px;color:#aeb0bd;margin-bottom:24px}.wide{width:100%;margin-top:7px}.result-stats{display:grid;grid-template-columns:repeat(3,1fr);padding:16px 0 18px;margin:0 0 8px;border-top:1px solid var(--line);border-bottom:1px solid var(--line)}.result-stats div{display:flex;flex-direction:column;gap:5px}.result-stats b{font:700 24px 'Barlow Condensed'}.result-stats small{font-size:7px;letter-spacing:1px;color:#9da0ae}#toast{position:absolute;z-index:9;left:50%;bottom:28px;transform:translate(-50%,20px);padding:11px 17px;background:#202332;border:1px solid var(--line);font-size:11px;opacity:0;pointer-events:none;transition:.25s}#toast.show{opacity:1;transform:translate(-50%,0)}
@keyframes rise{from{opacity:0;transform:translateY(8px)}to{opacity:1;transform:translateY(0)}}@keyframes idle{0%,100%{transform:translateY(0)}50%{transform:translateY(-8px)}}
@media(max-width:800px){.chrome{height:65px;padding:0 5%}.home-copy{left:7%;top:21%;width:55%}h1{font-size:clamp(50px,10vw,76px)}.hero-card{right:5%;width:36vw;height:52vh;top:23%}.home-stats{gap:20px;margin-top:32px}.character-layout{left:5%;right:5%;grid-template-columns:34% 1fr;gap:15px;top:25%;bottom:11%}.character-detail{padding:15px}.detail-info{left:15px;right:15px;bottom:14px}.detail-info h3{font-size:30px}.roster{grid-template-columns:repeat(3,minmax(75px,1fr));gap:7px}.runner-card{min-height:100px}.screen-head{left:5%;right:5%;top:12%}.world-grid{left:5%;right:5%;gap:8px}.world-card{padding:10px}.world-card-content{left:10px;bottom:10px}.world-card h3{font-size:20px}.guide-grid{left:6%;right:6%;gap:8px}.guide-grid article{padding:15px}.guide-grid p{font-size:10px}}
@media(max-width:580px){#app{min-height:100dvh}.home-copy{top:15%;left:7%;width:86%}.home-copy>p{width:70%;font-size:12px}h1{font-size:62px;margin:17px 0}.hero-card{top:46%;right:8%;width:55vw;height:40vh;opacity:.82}.hero-figure{height:70%}.home-stats{margin-top:25px;gap:26px}.home-bottom{font-size:7px;bottom:15px}.home-bottom span:last-child{display:none}.screen-head{top:10%}.screen-head h2{font-size:34px}.character-layout{top:20%;bottom:8%;display:flex;flex-direction:column;gap:10px}.character-detail{height:36%;min-height:185px;flex-shrink:0}.detail-art{height:100%;top:-10%;right:9%}.detail-info{bottom:11px}.detail-info h3{font-size:26px}.detail-info p{margin-bottom:5px}.stat-list{display:none}.ability-label{font-size:7px}.ability-name{font-size:14px}.filter-row{overflow:auto;flex-shrink:0;margin:0 0 8px}.filter-chip{white-space:nowrap;padding:7px 10px}.roster{grid-template-columns:repeat(3,minmax(78px,1fr));}.runner-card{min-height:88px}.runner-avatar{transform:scale(.5)}.screen-footer{display:none}.world-grid{top:22%;bottom:23%;height:auto;grid-template-columns:repeat(2,1fr);gap:8px}.world-card h3{font-size:21px}.world-bottom{bottom:8%;align-items:flex-start;gap:10px;flex-direction:column}.world-bottom .primary{width:100%;padding:13px}.world-selected{font-size:8px}.guide-grid{top:20%;bottom:6%;grid-template-columns:repeat(2,1fr);gap:8px}.guide-grid article{min-height:0;padding:13px}.guide-grid article>b{font-size:25px}.guide-grid h3{margin:12px 0 6px;font-size:16px}.guide-grid p{font-size:9px;min-height:unset;margin-bottom:12px}.modal-card{padding:28px 22px}.eyebrow{font-size:8px}.brand{font-size:17px}.brand-mark{width:30px;height:30px}.top-right{gap:13px}}

(() => {
'use strict';
const $=s=>document.querySelector(s), canvas=$('#game'), ctx=canvas.getContext('2d');
const chars=[
 {name:'Naruto Uzumaki',world:'Naruto',tag:'THE HIDDEN FLAME',ability:'Rasengan Dash',colors:['#ff812e','#31559c','#f6c39c'],hair:'spikes',mark:'☯',stats:[90,72,80]},
 {name:'Adult Sasuke',world:'Naruto',tag:'SHADOW OF THE UCHIHA',ability:'Chidori Surge',colors:['#283145','#6558a8','#d8b8a5'],hair:'sweep',mark:'◉',stats:[78,92,76]},
 {name:'Kurama',world:'Naruto',tag:'NINE-TAILED TITAN',ability:'Tailed Beast Pulse',colors:['#fb762f','#e04732','#ffd05d'],hair:'flame',mark:'狐',stats:[96,68,88]},
 {name:'Yuji Itadori',world:'Jujutsu Kaisen',tag:'VESSEL OF CURSES',ability:'Divergent Impact',colors:['#d95d57','#7b3246','#eab798'],hair:'crop',mark:'虎',stats:[83,78,84]},
 {name:'Ryomen Sukuna',world:'Jujutsu Kaisen',tag:'KING OF CURSES',ability:'Malevolent Burst',colors:['#ee746d','#682f46','#edbaa0'],hair:'spikes',mark:'呪',stats:[98,88,73]},
 {name:'Satoru Gojo',world:'Jujutsu Kaisen',tag:'THE LIMITLESS',ability:'Infinity Break',colors:['#eff3ff','#536fbd','#e8c2ad'],hair:'spikes',mark:'∞',stats:[87,95,91]},
 {name:'Tanjiro Kamado',world:'Demon Slayer',tag:'WATER & SUN',ability:'Hinokami Flow',colors:['#253347','#a43b3b','#e6b99f'],hair:'crop',mark:'水',stats:[85,79,88]},
 {name:'Nezuko Kamado',world:'Demon Slayer',tag:'NIGHT BLOOM',ability:'Blood Moon Bloom',colors:['#342339','#e88b9b','#f2c5ad'],hair:'long',mark:'花',stats:[79,86,94]},
 {name:'Inosuke Hashibira',world:'Demon Slayer',tag:'BEAST BREATHING',ability:'Beast Pounce',colors:['#a6c4df','#6584a8','#f1cbb2'],hair:'wild',mark:'牙',stats:[95,75,69]},
 {name:'Zenitsu Agatsuma',world:'Demon Slayer',tag:'THUNDERCLAP',ability:'Thunder Flash',colors:['#f4c64d','#df8930','#f2bea0'],hair:'spikes',mark:'雷',stats:[87,89,82]},
 {name:'Saitama',world:'One Punch Man',tag:'CAPED BALD-E',ability:'Serious Series',colors:['#e8c944','#d64a44','#f2c7a6'],hair:'bald',mark:'拳',stats:[99,83,74]},
 {name:'Genos',world:'One Punch Man',tag:'DEMON CYBORG',ability:'Incineration Cannon',colors:['#e4d7b8','#d5a333','#efbd9a'],hair:'spikes',mark:'⚙',stats:[88,93,79]},
 {name:'Tatsumaki',world:'One Punch Man',tag:'TORNADO OF TERROR',ability:'Psychic Tempest',colors:['#29372e','#65cc83','#e9bca6'],hair:'long',mark:'✧',stats:[82,97,96]}
];
const worlds=[
 {name:'Hidden Leaf',universe:'Naruto',glyph:'木',desc:'Where the will of fire never fades.',colors:['#243f43','#83c47b','#edbd63'],sky:['#18273a','#536875','#d39368']},
 {name:'Cursed Tokyo',universe:'Jujutsu Kaisen',glyph:'呪',desc:'A city haunted by unseen forces.',colors:['#332c50','#a47be1','#e78ac2'],sky:['#17172e','#51446b','#bd7296']},
 {name:'Wisteria Pass',universe:'Demon Slayer',glyph:'藤',desc:'A moonlit path through ancient woods.',colors:['#293e44','#78dfc3','#e5b3e4'],sky:['#101f32','#344f64','#b383a4']},
 {name:'Neo City',universe:'One Punch Man',glyph:'拳',desc:'The skyline is just another challenge.',colors:['#333b4b','#ff9c65','#e6d677'],sky:['#192439','#536579','#d89072']}
];
const state={screen:'home',char:0,world:0,filter:'All',coins:+localStorage.getItem('ar-coins')||0,best:+localStorage.getItem('ar-best')||0,audio:true,run:null,last:0,w:0,h:0,dpr:1,toastTimer:0};
const clamp=(v,a,b)=>Math.max(a,Math.min(b,v));
function resize(){state.dpr=Math.min(devicePixelRatio||1,2);state.w=innerWidth;state.h=innerHeight;canvas.width=Math.floor(state.w*state.dpr);canvas.height=Math.floor(state.h*state.dpr);ctx.setTransform(state.dpr,0,0,state.dpr,0,0)}
addEventListener('resize',resize);resize();
function show(id){document.querySelectorAll('.screen').forEach(e=>e.classList.remove('visible'));$('#'+id).classList.add('visible');state.screen=id;}
function toast(msg){const t=$('#toast');t.textContent=msg;t.classList.add('show');clearTimeout(state.toastTimer);state.toastTimer=setTimeout(()=>t.classList.remove('show'),2100)}
function saveCoins(){localStorage.setItem('ar-coins',state.coins);$('#coin-total').textContent=String(state.coins).padStart(5,'0')}
saveCoins();
function characterFigure(index,mini=false){const c=chars[index];return `<div class="hero-figure ${mini?'mini-figure':''}" style="--hair:${c.colors[0]};--suit:${c.colors[1]};--skin:${c.colors[2]}"><span class="hero-cape"></span><span class="hero-head ${c.hair}"><i></i><b>${c.mark}</b></span><span class="hero-body"></span><span class="hero-leg left"></span><span class="hero-leg right"></span><span class="hero-aura"></span></div>`}
function renderRoster(){const filters=['All',...worlds.map(w=>w.universe)];$('#character-filters').innerHTML=filters.map(f=>`<button class="filter-chip ${state.filter===f?'active':''}" data-filter="${f}">${f.toUpperCase()}</button>`).join('');const shown=chars.map((c,i)=>({...c,i})).filter(c=>state.filter==='All'||c.world===state.filter);$('#roster').innerHTML=shown.map(c=>`<button class="runner-card ${c.i===state.char?'active':''}" data-char="${c.i}" style="--card-color:${c.colors[1]}66"><span class="runner-avatar">${characterFigure(c.i,true)}</span><b>${c.name}</b><small>${c.world.toUpperCase()}</small></button>`).join('');renderDetail()}
function renderDetail(){const c=chars[state.char];const bars=['SPEED','POWER','FOCUS'];$('#character-detail').innerHTML=`<div class="detail-art">${characterFigure(state.char)}</div><div class="detail-info"><div class="detail-tag">${c.tag}</div><h3>${c.name.toUpperCase()}</h3><p>${c.world.toUpperCase()} UNIVERSE · RUNNER #${String(state.char+1).padStart(2,'0')}</p><div class="stat-list">${c.stats.map((v,i)=>`<div class="stat">${bars[i]}<i style="--v:${v}%"></i></div>`).join('')}</div><div class="ability-label">SIGNATURE ABILITY</div><div class="ability-name">✦ &nbsp;${c.ability}</div></div>`}
function renderWorlds(){const cmap=['#78c48b','#bd85dd','#72d9c6','#ffa36e'];$('#world-grid').innerHTML=worlds.map((w,i)=>`<button class="world-card ${i===state.world?'active':''}" data-world="${i}" style="--world:${w.colors[0]};--accent:${cmap[i]}"><div class="world-art"></div><span class="world-glyph">${w.glyph}</span><div class="world-card-content"><small>DIMENSION 0${i+1} · ${w.universe.toUpperCase()}</small><h3>${w.name.toUpperCase()}</h3><p>${w.desc}</p></div></button>`).join('');updateWorldLabel()}
function updateWorldLabel(){const w=worlds[state.world];$('#world-selected').innerHTML=`CURRENT DESTINATION <b>${w.name.toUpperCase()}</b>`}
renderRoster();renderWorlds();
$('#start-btn').onclick=()=>{state.filter='All';renderRoster();show('characters')};$('#how-btn').onclick=()=>show('howto');$('#audio-btn').onclick=()=>{state.audio=!state.audio;$('#audio-btn').textContent=state.audio?'♫':'♪';toast(state.audio?'SOUND ENABLED':'SOUND MUTED')};
document.querySelectorAll('[data-back]').forEach(b=>b.onclick=()=>show(b.dataset.back));
$('#roster').addEventListener('click',e=>{const b=e.target.closest('[data-char]');if(!b)return;state.char=+b.dataset.char;renderRoster()});$('#character-filters').addEventListener('click',e=>{const b=e.target.closest('[data-filter]');if(!b)return;state.filter=b.dataset.filter;renderRoster()});
$('#characters').querySelector('.screen-head .back-btn').onclick=()=>show('home');
$('#roster').addEventListener('dblclick',e=>{if(e.target.closest('[data-char]'))show('worlds')});
$('#world-grid').addEventListener('click',e=>{const b=e.target.closest('[data-world]');if(!b)return;state.world=+b.dataset.world;renderWorlds()});$('#world-play').onclick=startRun;
$('#resume-btn').onclick=()=>{if(state.run){state.run.paused=false;show('game')} };
$('#quit-btn').onclick=()=>finishRun(false);$('#retry-btn').onclick=startRun;$('#result-home').onclick=()=>show('home');

